// Load per-language event outputs if present (generated by event_fetcher)
import jpEvents from './events/blog_jp_output.json';
import zhEvents from './events/blog_zh_output.json';

function buildEventGalleryFromList(list) {
  if (!Array.isArray(list)) return [];
  const items = list.flatMap((ev) => {
    if (Array.isArray(ev.media_urls) && ev.media_urls.length > 0) {
      return ev.media_urls.map((m) => ({
        src: m.src,
        alt: ev.title || m.alt || 'Event',
        url: ev.url,
        startTime: ev.start_time,
        endTime: ev.end_time,
      }));
    }
    return [{
      src: '/images/shared/event-hero-placeholder.svg',
      alt: ev.title || 'Event',
      url: ev.url,
      startTime: ev.start_time,
      endTime: ev.end_time,
    }];
  });
  return items;
}

const jpGallery = jpEvents && Array.isArray(jpEvents.events) ? buildEventGalleryFromList(jpEvents.events) : [];
const zhGallery = zhEvents && Array.isArray(zhEvents.events) ? buildEventGalleryFromList(zhEvents.events) : [];
const combinedEvents = [];
if (jpEvents && Array.isArray(jpEvents.events)) combinedEvents.push(...jpEvents.events);
if (zhEvents && Array.isArray(zhEvents.events)) combinedEvents.push(...zhEvents.events);
const combinedGallery = buildEventGalleryFromList(combinedEvents);

